test.beforeAll(async({},info)=>{const port=7300+info.workerIndex;base=`http://127.0.0.1:${port}`;server=spawn(process.execPath,['--input-type=module','-e',`import {createServer} from 'vite';const s=await createServer({mode:'live-dev',cacheDir:'node_modules/.cache/phase5-independent-${port}',server:{host:'127.0.0.1',port:${port},strictPort:true}});await s.listen();`],{env:{...process.env,VITE_FIREBASE_PROJECT_ID:'clever-oasis-508610-n7',VITE_FIREBASE_AUTH_DOMAIN:'clever-oasis-508610-n7.firebaseapp.com',VITE_FIREBASE_API_KEY:'synthetic-public-key',VITE_FIREBASE_APP_ID:'synthetic-app',VITE_API_ORIGIN:'https://mw-credit-app-read-dev-test.run.app',VITE_COMMAND_API_ORIGIN:'https://mw-credit-app-command-dev-test.run.app',VITE_COMMAND_MODE:'dev-owner-testing'},stdio:'pipe'});await expect.poll(async()=>{try{return(await fetch(base)).status}catch{return 0}},{timeout:20000}).toBe(200)});
test.afterAll(()=>server?.kill());test.setTimeout(40000);
// Synthetic auth/HTTP seams with real DOM. Does not claim live authentication or durable operation journal.
const auth=`let listener;const user={uid:'phase5-independent-owner',getIdToken:async()=>'synthetic-bearer'};export const browserLocalPersistence='local',inMemoryPersistence='memory',browserPopupRedirectResolver={};export function initializeAuth(){return {}};export function onAuthStateChanged(a,fn){listener=fn;fn(localStorage.getItem('phase5-owner')?user:null);return()=>{}};export class GoogleAuthProvider{setCustomParameters(){}};export async function signInWithPopup(){localStorage.setItem('phase5-owner','1');listener(user)};export async function signOut(){localStorage.removeItem('phase5-owner');listener(null)};`;
const fields={name:'ผู้กู้จำลองชื่อยาว / Synthetic borrower',description:'English synthetic name',communicationName:'ชื่อที่ใช้ติดต่อ',instagramUsername:'synthetic_instagram',city:'Bangkok',workingLocation:'Synthetic office',address:'บรรทัดหนึ่ง\nline two',hidden:null,referrerId:'C-referrer',preferredReceivingAccountId:'C-account',note:'หมายเหตุ ไทย\n exact note '};
const record={...fields,id:'C-borrower',version:'a'.repeat(64),createdDate:'2026-10-08',aiCollectionEnabled:true,details:{preferredReceivingAccountLabel:'Synthetic receiving account',referrerName:'ผู้แนะนำจำลอง',hasActiveLoan:true,hasClosedLoan:true,totalAmountLoaned:'200',totalInterestEarned:'75',totalNumberOfLoans:2,outstandingPrincipal:'100',activeInterest:'25',activeReturn:'0.25',activeProfit:'-75',coverageDate:'2026-10-10',closedPrincipal:'100',closedInterest:'50',closedReturn:'0.5'}};
const directory={...record,borrowerDisplayName:fields.name,displayName:fields.name,outstandingPrincipal:'100',totalProfitEarned:'75',hasActiveLoan:true};
type State={writes:any[],status:number,lost:boolean,holdOptions:boolean,releaseOptions?:()=>void,holdWrite:boolean,releaseWrite?:()=>void,statusReads:string[],pendingBeforePosts:any[],statusOutcome:string,readRequests:string[],commandReads:string[],loanAccounts:any[],loanRows:any[],expenseItem:any};
async function pending(page:Page){return page.evaluate(async()=>{const {ownerOfflineRepository}=await import('/apps/pwa/src/owner-offline.ts');return ownerOfflineRepository({issuer:'https://securetoken.google.com/clever-oasis-508610-n7',uid:'phase5-independent-owner'}).list('pending')})}
async function setup(page:Page){const s:State={writes:[],status:200,lost:false,holdOptions:false,holdWrite:false,statusReads:[],pendingBeforePosts:[],statusOutcome:'unresolved',readRequests:[],commandReads:[],loanAccounts:[{id:'C-account',label:'Synthetic Lisa lending account',isDefault:false,holderId:'ch:lisa',active:true,holderActive:true}],loanRows:[],expenseItem:expenseFullC};
 await page.route('**/deps/firebase_app.js*',r=>r.fulfill({contentType:'text/javascript',body:'export function initializeApp(){return {}}'}));await page.route('**/deps/firebase_auth.js*',r=>r.fulfill({contentType:'text/javascript',body:auth}));
 await page.route('https://mw-credit-app-read-dev-test.run.app/**',r=>{const path=new URL(r.request().url()).pathname;s.readRequests.push(path);return r.fulfill({contentType:'application/json',body:JSON.stringify({ok:true,source:'dev',businessDate:'2026-10-08',asOf:'2026-10-08T05:00:00Z',items:path.endsWith('/loans')?s.loanRows:[directory],item:path.includes('/loans/')?s.loanRows[0]:directory,nextCursor:null})})});
 await page.route('https://mw-credit-app-command-dev-test.run.app/**',async r=>{const path=new URL(r.request().url()).pathname,method=r.request().method();if(method==='GET')s.commandReads.push(path);let result:any={ok:true,items:[],nextCursor:null};
  if(path==='/api/preferences'){result={ok:true,item:{language:null}}} else if(path==='/api/expense-options'){if(s.holdOptions)await new Promise<void>(done=>s.releaseOptions=done);result={ok:true,businessDate:'2026-10-09',categories:expenseCategoriesUiC,accounts:[{id:'C-account',label:'Synthetic Dad paying account',holderId:'ch:dad',holderLabel:'Dad'}]}}
  else if(path==='/api/expense-records'){result={ok:true,items:[s.expenseItem],nextCursor:null}}
  else if(path.startsWith('/api/expense-records/')){result={ok:true,item:s.expenseItem}}
  else if(path==='/api/loan-options'){if(s.holdOptions)await new Promise<void>(done=>s.releaseOptions=done);result={ok:true,businessDate:'2026-10-09',accounts:s.loanAccounts}}
  else if(path==='/api/borrower-options'){if(s.holdOptions)await new Promise<void>(done=>s.releaseOptions=done);result={ok:true,accounts:[{id:'C-account',label:'Synthetic receiving account'}],referrers:[{id:'C-referrer',label:'ผู้แนะนำจำลอง'},{id:record.id,label:'Self must not appear'}]}}
  else if(path.endsWith('/close-preview')){if(s.holdOptions)await new Promise<void>(done=>s.releaseOptions=done);result={ok:true,businessDate:'2026-10-09',sourceVersion:loanFullC.version,amount:'115',planHash:'c'.repeat(64),accounts:s.loanAccounts}}
  else if(path.startsWith('/api/loan-records/')&&(path.endsWith('/charges')||path.endsWith('/payments'))){result={ok:true,items:[],nextCursor:null}}else if(path.startsWith('/api/loan-records/')){result={ok:true,item:loanFullC}}
  else if(path.startsWith('/api/payment-drafts/')){result={ok:true,mode:'dev-owner-testing',scope:'all',businessDate:'2026-10-09',asOf:'2026-10-09T05:00:00Z',borrower:{id:record.id,displayName:'Synthetic payment borrower'},accounts:[{id:'C-account',label:'Synthetic receiving account'}],charges:[{id:'C-charge',chargeDate:'2026-10-09',loanDisplayKey:'Synthetic loan',principalRemaining:'10',interestRemaining:'0',amountRemaining:'10'}],nextCursor:null}}
  else if(path.startsWith('/api/payment-commands/')){result={ok:true,kind:'unresolved',safeToUseNewRequestId:false}}
  else if(path.includes('/borrower-records')){expect(method).toBe('GET');result={ok:true,item:record};}
  else if(path==='/api/operations'&&method==='POST'){const body=r.request().postDataJSON();s.writes.push({method,body});s.pendingBeforePosts.push(await pending(page));if(s.holdWrite)await new Promise<void>(done=>s.releaseWrite=done);if(s.lost)return r.abort('failed');result={ok:s.status===200,kind:'recorded',originalOutcome:{status:s.status===200?'applied':'rejected',code:s.status===200?null:'source_conflict',result:s.status===200?{operation:body.operation,targetType:'borrower',targetId:body.targetId,paymentId:null,plan:null,predecessorRequestId:null}:null}};return r.fulfill({status:s.status,contentType:'application/json',body:JSON.stringify(result)}).catch(()=>{});}
  else if(path.startsWith('/api/operations/')){expect(method).toBe('GET');s.statusReads.push(path.split('/').at(-1)!);result=s.statusOutcome==='unresolved'?{ok:true,kind:'unresolved',safeToUseNewRequestId:false}:{ok:true,kind:'recorded',originalOutcome:{status:s.statusOutcome,code:s.statusOutcome==='rejected'?'source_conflict':null,result:null}};}
  if(result.item?.id&&result.item?.version){result.asOf=Date.now();result.businessDate='2026-10-09'}return r.fulfill({contentType:'application/json',body:JSON.stringify(result)}).catch(()=>{});
 });
 await page.route('https://mw-credit-app-command-dev-test.run.app/api/dashboard',r=>r.fulfill({contentType:'application/json',body:JSON.stringify({collection:{notPaid:0,partiallyPaid:0,overdue:0,fullyPaid:0},forecast:{},portfolio:{},incomeMtd:{},businessCashHeld:[]})}));await page.goto(base);await page.getByRole('button',{name:/Google/}).click();await chooseLanguage(page,'EN');await page.getByRole('button',{name:'Borrowers',exact:true}).filter({visible:true}).click();await expect(page.getByRole('button',{name:'Add borrower',exact:true})).toBeVisible();return s;
}
async function openSaved(page:Page){if(page.viewportSize()!.width<=1050)await page.getByRole('button',{name:'Open navigation',exact:true}).click();await page.getByRole('button',{name:'Saved payment drafts',exact:true}).filter({visible:true}).click()}
async function full(page:Page){await page.locator('.borrower-tile-main').click();await expect(page.getByRole('button',{name:'Edit borrower',exact:true})).toBeVisible()}

for(const width of [320,390,1440])test(`F2 borrower ordered fields/read-only metadata and compact geometry ${width}px`,async({page},info)=>{await page.setViewportSize({width,height:900});const s=await setup(page);await page.getByRole('button',{name:'Add borrower',exact:true}).click();const region=page.getByRole('region',{name:'Borrower record',exact:true});await expect(region.getByRole('button',{name:'Save borrower',exact:true})).toBeVisible();
 const labels=await region.locator('form>label').evaluateAll(es=>es.map(e=>e.childNodes[0]?.textContent?.trim()));expect(labels).toEqual(['Borrower Name - Thai','Creation Date','English Name','Preferred Receiving Cash Account','Communication Name','Instagram Username','AI Collection Enabled','City','Working Location','Address','Referrer','Borrower Note','Hide from Borrowers List']);
 await expect(region.getByRole('textbox',{name:/^Creation\ Date(?: \*)?$/})).toHaveCount(0);await expect(region.getByRole('checkbox',{name:'AI Collection Enabled',exact:true})).toHaveCount(0);await expect(region.getByRole('textbox',{name:/phone|document/i})).toHaveCount(0);
 for(const lang of ['EN','ไทย'] as const){await chooseLanguage(page,lang);expect(await page.locator('body').evaluate(e=>e.scrollWidth)).toBeLessThanOrEqual(width);expect(await page.evaluate(()=>document.documentElement.scrollWidth)).toBeLessThanOrEqual(width);await expect(page.locator('main')).not.toContainText(/Loading|Checking/);mkdirSync('outputs/r052-phase5-completion',{recursive:true});await page.screenshot({path:`outputs/r052-phase5-completion/borrower-form-${info.project.name}-${width}-${lang==='EN'?'en':'th'}.png`})}expect(s.writes).toHaveLength(0);
});

test('F2 full detail groups precede contact fields, exact notes/referrer and related navigation remain available',async({page})=>{const s=await setup(page);await full(page);const region=page.getByRole('region',{name:'Borrower record',exact:true});await expect(region).toContainText('Active Loans');await expect(region).toContainText('Closed Loans');await expect(region).toContainText('ผู้แนะนำจำลอง');await expect(region).toContainText(fields.note.trim());const order=await region.evaluate(e=>{const nodes=Array.from(e.querySelectorAll('h3,label'));return nodes.map(n=>n.textContent||'')});expect(order.findIndex(t=>t==='Active Loans')).toBeLessThan(order.findIndex(t=>t.startsWith('Communication Name')));await expect(region.getByRole('region',{name:'Related loans',exact:true})).toBeVisible();expect(s.writes).toHaveLength(0)});

test('F1 durable CAS rejection preserves exact edit, header-only busy and persisted-before-POST payload',async({page})=>{const s=await setup(page);await full(page);await page.getByRole('button',{name:'Edit borrower',exact:true}).click();await expect(page.getByRole('option',{name:'Self must not appear',exact:true})).toHaveCount(0);await page.getByRole('textbox',{name:/^Borrower\ Note(?: \*)?$/}).fill('new exact ไทย');s.status=422;s.holdWrite=true;await page.getByRole('button',{name:'Save borrower',exact:true}).click();await expect.poll(()=>!!s.releaseWrite).toBe(true);await expect(page.locator('.topbar .collection-update')).toContainText('Loading');await expect(page.locator('main')).not.toContainText(/Loading|Checking|Saving/);await expect(page.getByRole('button',{name:'Save borrower',exact:true})).toBeDisabled();const command=s.writes[0].body;expect(command).toMatchObject({operation:'borrower.update',targetId:record.id,expectedVersion:record.version,predecessorRequestId:null,receiptId:null,inputs:{note:'new exact ไทย',hidden:null}});expect(s.pendingBeforePosts[0]).toHaveLength(1);expect(s.pendingBeforePosts[0][0].value).toEqual({domain:'borrower',command});s.releaseWrite!();await expect(page.getByText('The record changed. Reload it before editing again.',{exact:true})).toBeVisible();await expect(page.getByRole('textbox',{name:/^Borrower\ Note(?: \*)?$/})).toHaveValue('new exact ไทย');await expect.poll(async()=>(await pending(page)).length).toBe(0);expect(s.writes).toHaveLength(1);await page.getByRole('button',{name:'Check current borrower',exact:true}).click();await expect(page.getByRole('button',{name:'Edit borrower',exact:true})).toBeVisible();expect(s.writes).toHaveLength(1)});

test('F1 durable Unknown is immutable across reload and saved-workspace GET-only status recovery',async({page})=>{const s=await setup(page);await full(page);await page.getByRole('button',{name:'Edit borrower',exact:true}).click();await page.getByRole('textbox',{name:/^Borrower\ Note(?: \*)?$/}).fill('unknown attempt ไทย');s.lost=true;await page.getByRole('button',{name:'Save borrower',exact:true}).click();await expect(page.getByText('Outcome unknown. Check this request before making another change.',{exact:true})).toBeVisible();const command=s.writes[0].body;await expect(page.getByText(command.requestId,{exact:true})).toBeVisible();await expect(page.getByRole('button',{name:'Edit borrower',exact:true})).toHaveCount(0);await expect(page.getByRole('button',{name:'Save borrower',exact:true})).toHaveCount(0);expect((await pending(page))[0].value).toEqual({domain:'borrower',command});await page.reload();await page.getByRole('button',{name:'Borrowers',exact:true}).filter({visible:true}).click();await expect(page.getByRole('button',{name:'Add borrower',exact:true})).toBeVisible();expect(s.writes).toHaveLength(1);expect(s.statusReads).toHaveLength(0);await openSaved(page);await page.getByRole('button',{name:/^Pending borrower change/}).click();await expect(page.getByText(command.requestId,{exact:true})).toBeVisible();await expect(page.getByRole('button',{name:'Save borrower',exact:true})).toHaveCount(0);await page.getByRole('button',{name:'Check current borrower',exact:true}).click();await expect.poll(()=>s.statusReads.length).toBe(1);await expect(page.getByText('Outcome unknown. Check this request before making another change.',{exact:true})).toBeVisible();expect((await pending(page))[0].value).toEqual({domain:'borrower',command});expect(s.writes).toHaveLength(1);s.statusOutcome='applied';await page.getByRole('button',{name:'Check current borrower',exact:true}).click();await expect.poll(async()=>(await pending(page)).length).toBe(0);expect(s.statusReads).toEqual([command.requestId,command.requestId]);expect(s.writes).toHaveLength(1)});

test('F12 pending storage failure sends no operation and leaves exact unsent fields editable',async({page})=>{const s=await setup(page);await full(page);await page.getByRole('button',{name:'Edit borrower',exact:true}).click();await page.getByRole('textbox',{name:/^Borrower\ Note(?: \*)?$/}).fill('not sent ไทย');await page.evaluate(()=>{const original=IDBObjectStore.prototype.put;(window as any).originalPut=original;IDBObjectStore.prototype.put=function(value:any,...rest:any[]){if(value.kind==='pending')throw new DOMException('Synthetic quota','QuotaExceededError');return original.call(this,value,...rest)}});await page.getByRole('button',{name:'Save borrower',exact:true}).click();await expect(page.getByText('Request was not sent. Device storage is unavailable or full.',{exact:true})).toBeVisible();expect(s.writes).toHaveLength(0);expect(await pending(page)).toHaveLength(0);await expect(page.getByRole('textbox',{name:/^Borrower\ Note(?: \*)?$/})).toHaveValue('not sent ไทย');await expect(page.getByRole('button',{name:'Save borrower',exact:true})).toBeEnabled();await page.evaluate(()=>{IDBObjectStore.prototype.put=(window as any).originalPut});});

test('F12 restored Unknown rejection never silently rebases original CAS or retries dispatch',async({page})=>{const s=await setup(page);await full(page);await page.getByRole('button',{name:'Edit borrower',exact:true}).click();await page.getByRole('textbox',{name:/^Borrower\ Note(?: \*)?$/}).fill('preserved rejected draft');s.lost=true;await page.getByRole('button',{name:'Save borrower',exact:true}).click();await expect(page.getByText('Outcome unknown. Check this request before making another change.',{exact:true})).toBeVisible();const command=s.writes[0].body;await page.reload();await page.getByRole('button',{name:'Borrowers',exact:true}).filter({visible:true}).click();await expect(page.getByRole('button',{name:'Add borrower',exact:true})).toBeVisible();await openSaved(page);await page.getByRole('button',{name:/^Pending borrower change/}).click();s.statusOutcome='rejected';await page.getByRole('button',{name:'Check current borrower',exact:true}).click();await expect(page.getByText('The record changed. Reload it before editing again.',{exact:true})).toBeVisible();await expect(page.getByRole('textbox',{name:/^Borrower\ Note(?: \*)?$/})).toHaveCount(0);await expect(page.getByRole('button',{name:'Edit borrower',exact:true})).toHaveCount(0);await expect(page.getByRole('region',{name:'Borrower record',exact:true})).toContainText('preserved rejected draft');await expect.poll(async()=>(await pending(page)).length).toBe(0);expect(s.writes).toHaveLength(1);expect(command.expectedVersion).toBe(record.version);await page.getByRole('button',{name:'Check current borrower',exact:true}).click();await expect(page.getByRole('button',{name:'Edit borrower',exact:true})).toBeVisible();expect(s.writes).toHaveLength(1)});


