for(const domain of ['borrower','loan','charge'] as const)test(`F12 ${domain} unsent exact reload converts to immutable pending before explicit POST`,async({page})=>{const s=await setup(page);if(domain==='borrower'){await full(page);await page.getByRole('button',{name:'Edit borrower',exact:true}).click();await page.getByRole('textbox',{name:/^Borrower\ Note(?: \*)?$/}).fill('saved borrower exact ไทย')}else if(domain==='loan'){await loanForm(page);await loanValues(page)}else{await fullLoan(page,s);await page.getByRole('button',{name:'New charge',exact:true}).click();await expect(page.getByLabel(/^Charge\ Date(?: \*)?$/)).toHaveValue('2026-10-09');await page.getByRole('spinbutton',{name:/^Principal\ Due(?: \*)?$/}).fill('12.25');await page.getByRole('spinbutton',{name:/^Interest\ Due(?: \*)?$/}).fill('-1.25');await page.getByRole('textbox',{name:/^Notes(?: \*)?$/}).fill('saved charge exact ไทย')}
 await expect.poll(async()=>(await draftsC(page)).filter(r=>r.value.domain===domain).length).toBe(1);const saved=(await draftsC(page)).find(r=>r.value.domain===domain)!;expect(s.writes).toHaveLength(0);await page.reload();await page.getByRole('button',{name:'Borrowers',exact:true}).filter({visible:true}).click();await expect(page.getByRole('button',{name:'Add borrower',exact:true})).toBeVisible();expect(s.writes).toHaveLength(0);expect(s.statusReads).toHaveLength(0);await openSaved(page);const workspace=page.getByRole('region',{name:'Saved offline payment drafts',exact:true});const row=workspace.getByRole('button').filter({hasText:saved.value.label});await expect(row).toHaveCount(1);await row.click();
 if(domain==='borrower'){await expect(page.getByRole('textbox',{name:/^Borrower\ Note(?: \*)?$/})).toHaveValue('saved borrower exact ไทย')}else if(domain==='loan'){await expect(loanMoneyC(page,'Principal Amount')).toHaveValue('100.25');await expect(page.getByRole('textbox',{name:/^Loan\ Arrangement(?: \*)?$/})).toHaveValue('exact ไทย arrangement')}else{await expect(page.getByRole('spinbutton',{name:/^Principal\ Due(?: \*)?$/})).toHaveValue('12.25');await expect(page.getByRole('spinbutton',{name:/^Interest\ Due(?: \*)?$/})).toHaveValue('-1.25');await expect(page.getByRole('textbox',{name:/^Notes(?: \*)?$/})).toHaveValue('saved charge exact ไทย')}
 expect(s.writes).toHaveLength(0);s.lost=true;if(domain==='charge'){await page.getByRole('button',{name:'Review change',exact:true}).click();expect(s.writes).toHaveLength(0);await page.getByRole('button',{name:'Confirm',exact:true}).click()}else await page.getByRole('button',{name:domain==='borrower'?'Save borrower':'Save loan',exact:true}).click();await expect.poll(()=>s.pendingBeforePosts.length).toBe(1);const command=s.writes[0].body;expect(command.operation).toBe(domain==='borrower'?'borrower.update':domain+'.create');expect(command.targetId).toBe(saved.value.draft.id);expect(command.expectedVersion).toBe(domain==='borrower'?record.version:null);expect(command.inputs).toEqual(domain==='charge'?{loanId:saved.value.draft.loanId,chargeDate:saved.value.draft.date,principalDue:saved.value.draft.principal,interestDue:saved.value.draft.interest,notes:saved.value.draft.notes}:saved.value.draft.fields);expect(s.pendingBeforePosts[0][0].value).toMatchObject({domain,command});await expect.poll(async()=>(await draftsC(page)).filter(r=>r.value.domain===domain).length).toBe(0);const locked=(await pending(page))[0].value;await page.reload();await page.getByRole('button',{name:'Borrowers',exact:true}).filter({visible:true}).click();await expect(page.getByRole('button',{name:'Add borrower',exact:true})).toBeVisible();expect(s.writes).toHaveLength(1);expect(s.statusReads).toHaveLength(0);expect((await pending(page))[0].value).toEqual(locked);await openSaved(page);await expect(page.getByRole('region',{name:'Saved offline payment drafts',exact:true})).toContainText(locked.borrowerLabel??(domain==='borrower'?'Pending borrower change':domain==='loan'?'Pending loan change':'New charge'));expect(s.writes).toHaveLength(1)});

test('F12 missing-domain legacy payment draft decodes with current component review without auto command or eviction',async({page})=>{const s=await setup(page);let commands=0;page.on('request',r=>{if(r.method()==='POST'&&new URL(r.url()).pathname==='/api/payment-commands')commands++});await page.evaluate(async(id)=>{const repo=(await import('/apps/pwa/src/owner-offline.ts')).ownerOfflineRepository({issuer:'https://securetoken.google.com/clever-oasis-508610-n7',uid:'phase5-independent-owner'});await repo.saveDraft(id,{formVersion:5,notes:'legacy retained ไทย',paymentMethod:'Cash',account:'C-account',selectionRows:[{id:'C-charge',chargeDate:'2026-10-09',loanDisplayKey:'Synthetic loan',amountRemaining:'10'}],allMode:false})},record.id);await openSaved(page);await page.getByRole('button',{name:/^Saved draft/}).click();await expect(page.getByRole('textbox',{name:/^Notes(?: \*)?$/})).toHaveValue('legacy retained ไทย');await expect(page.getByRole('textbox',{name:/^Amount\ received(?: \*)?$/})).toHaveValue('10');await expect(page.getByRole('textbox',{name:/^Principal\ for\ Synthetic\ loan\ 2026-10-09(?: \*)?$/})).toHaveValue('10');await expect(page.getByRole('checkbox',{name:'Allocate to Synthetic loan 2026-10-09',exact:true})).toBeChecked();await expect(page.getByText('Saved selection needs conversion review with current component balances.',{exact:true})).toBeVisible();expect(commands).toBe(0);expect(s.writes).toHaveLength(0);expect(await pending(page)).toHaveLength(0);expect(await draftsC(page)).toHaveLength(1)});
const dashboardUiC={businessDate:'2026-10-09',asOf:'2026-10-09T05:00:00Z',pendingPaymentAmount:'27',todayProfit:'4',yesterdayProfit:'3',netProfit:'-8',collection:{notPaid:0,partiallyPaid:2,overdue:1,fullyPaid:3},forecast:{expectedDailyInterest:'6',realizedProfitMtd:'12',forecastRemainingInterest:'100',projectedMonthlyProfit:'112'},portfolio:{totalCashPool:'200',activeLoanProfit:'-9',profitCoverageRatio:'0.25'},incomeMtd:{operatingIncomeMtd:'12',expensesMtd:'20',netProfitMtd:'-8',tommyWithdrawnMtd:'1',lisaWithdrawnMtd:'2',unsettledProfitMtd:'-11'},businessCashHeld:[{id:'C-account',label:'Synthetic custody account',holderId:'ch:lisa',holderLabel:'Lisa',currentBalance:null}]};
async function navigateReadC(page:Page,name:string){const button=page.getByRole('button',{name,exact:true}).filter({visible:true});if(!await button.count())await page.getByRole('button',{name:'Open navigation',exact:true}).click();await page.getByRole('button',{name,exact:true}).filter({visible:true}).click()}
test('F11 UI Dashboard exact groups zero-status suppression header busy and strict320 EN Thai',async({page},info)=>{
 await page.setViewportSize({width:320,height:900});const s=await setup(page);let release:()=>void=()=>{};let requests=0;await page.route('https://mw-credit-app-command-dev-test.run.app/api/dashboard',async r=>{requests++;await new Promise<void>(done=>release=done);await r.fulfill({contentType:'application/json',body:JSON.stringify(dashboardUiC)})});await navigateReadC(page,'Dashboard');await expect.poll(()=>requests).toBe(1);await expect(page.locator('.topbar .collection-update')).toContainText('Loading');await expect(page.locator('main')).not.toContainText(/Loading|Checking/);release();const region=page.getByRole('region',{name:'Dashboard',exact:true});await expect(region.getByRole('heading',{name:'KPIs',exact:true})).toBeVisible();expect(await region.locator('h2,h3').allTextContents()).toEqual(['KPIs','Collection','Monthly Forecast','Active loans','Income MTD','Business Cash Held','Lisa']);await expect(region.getByText('Not Paid',{exact:true})).toHaveCount(0);await expect(region.getByText('Partially Paid',{exact:true})).toBeVisible();await expect(region.getByText('25%',{exact:true})).toBeVisible();await expect(region.getByText('Unavailable',{exact:true})).toBeVisible();await expect(region).not.toContainText(/Outstanding Principal|Total Outstanding/);await expect(region.getByRole('button')).toHaveCount(0);
 for(const lang of ['EN','ไทย'] as const){await chooseLanguage(page,lang);expect(await page.locator('body').evaluate(e=>e.scrollWidth)).toBeLessThanOrEqual(320);expect(await page.evaluate(()=>document.documentElement.scrollWidth)).toBeLessThanOrEqual(320);await expect(page.locator('main')).not.toContainText(/Loading|Checking/);await page.screenshot({path:'outputs/r052-phase5-completion/dashboard-'+info.project.name+'-'+(lang==='EN'?'en':'th')+'.png'})}expect(s.writes).toHaveLength(0);
});
