 await page.setViewportSize({width:320,height:900});const s=await setup(page);let detailUrl='',fail=false;const context={businessDate:'2026-10-09',asOf:'2026-10-09T05:00:00Z',forecastNote:'Recorded and projected context; synthetic only.'};await page.route('https://mw-credit-app-command-dev-test.run.app/api/upcoming-charges**',async r=>{const url=new URL(r.request().url());if(fail)return r.fulfill({status:409,contentType:'application/json',body:'{"ok":false}'});const detail=url.pathname!='/api/upcoming-charges';if(detail)detailUrl=url.toString();await r.fulfill({contentType:'application/json',body:JSON.stringify(detail?{...context,dueDate:'2026-10-16',totalCharge:'37',items:[{id:'C-event',loanDate:'2026-10-01',loanType:'Daily Loan',loanPrincipal:'100',amount:'11',basis:'Recorded'}],nextCursor:null}:{...context,dateTotals:[{date:'2026-10-10',amount:'26'},{date:'2026-10-16',amount:'37'}],items:[{id:'C-one',borrowerId:'C-future',label:'Synthetic future-only borrower',dueDate:'2026-10-10',totalCharge:'26'},{id:'C-seven',borrowerId:'C-future',label:'Synthetic seventh date borrower',dueDate:'2026-10-16',totalCharge:'37'}],nextCursor:null})})});await navigateReadC(page,'Upcoming Charges');const region=page.getByRole('region',{name:'Upcoming Charges',exact:true});await expect(region.getByRole('heading',{name:'16-Oct · ฿37',exact:true})).toBeVisible();await expect(region.getByRole('button',{name:/Previous upcoming page|Next upcoming page|Refresh/})).toHaveCount(0);await region.getByRole('button',{name:'Synthetic seventh date borrower ฿37',exact:true}).click();await expect(region.locator('.upcoming-row small').filter({hasText:/Recorded$/})).toBeVisible();expect(new URL(detailUrl).pathname).toBe('/api/upcoming-charges/C-future/2026-10-16');expect(new URL(detailUrl).searchParams.get('businessDate')).toBe('2026-10-09');await expect(region.getByRole('heading',{name:'16-Oct · ฿37',exact:true})).toBeVisible();
 for(const lang of ['EN','ไทย'] as const){await chooseLanguage(page,lang);expect(await page.locator('body').evaluate(e=>e.scrollWidth)).toBeLessThanOrEqual(320);await expect(page.locator('main')).not.toContainText(/Loading|Checking/);await page.screenshot({path:'outputs/r052-phase5-completion/upcoming-'+info.project.name+'-'+(lang==='EN'?'en':'th')+'.png'})}await chooseLanguage(page,'EN');fail=true;await page.locator('.topbar').getByRole('button',{name:'Refresh Upcoming Charges',exact:true}).click();await expect(region.getByRole('button',{name:'Retry Upcoming Charges',exact:true})).toBeVisible();fail=false;await region.getByRole('button',{name:'Retry Upcoming Charges',exact:true}).click();await expect(region.getByRole('alert')).toHaveCount(0);await expect(region.locator('.upcoming-row small').filter({hasText:/Recorded$/})).toBeVisible();expect(s.writes).toHaveLength(0);
